insert into dai_mcq_rule (ma, ten, mo_ta, vi_du, nhom, ap_dung, du_phong, active) values
('R525','Phần trăm của một số: chia thay vì nhân (hoặc nhân thay vì chia)','Tìm p% của M mà tính M : p% (hoặc tìm số khi biết p% của nó mà tính M × p%). Tính ra kết quả thật của phép ngược.','40% của 45 kg → 45 : 40% = 112,5','khai_niem',array['NDB02769','NDB02770','NDB02771','NDB02772','NDB02773','NDB03001'],false,true),
('R526','Cộng/trừ thẳng các phần trăm thay vì nhân hai tỉ số','Tăng a% rồi giảm b% (hoặc giảm kép) mà tính a% − b% (hay a% + b%) thay vì nhân (100%±a%) × (100%±b%). Tính ra kết quả thật.','Giảm 20% rồi giảm 10% → giảm 30%','khai_niem',array['NDB02774','NDB02775','NDB02776','NDB03002','NDB03003','NDB03006'],false,true),
('R527','Phần trăm tính trên sai số gốc','Lấy phần trăm của số sai (giá bán thay vì giá gốc, số sau thay vì số đầu, tổng thay vì phần). Tính ra kết quả thật.','Lãi 25% so với giá gốc → lấy 25% của giá bán','khai_niem',array['NDB02771','NDB02772','NDB02773','NDB02775','NDB03001','NDB03006','NDB03553'],false,true),
('R528','Nhầm "bằng bao nhiêu %" với "hơn/kém bao nhiêu %" (quên trừ 100%)','Tìm được số sau bằng x% số trước nhưng ghi luôn x% là phần tăng/giảm (hoặc cộng thêm 100%) thay vì x% − 100% (100% − x%).','64 so với 40 là 160% → ghi "nhiều hơn 160%"','khai_niem',array['NDB03001','NDB02775','NDB02776','NDB03002','NDB03003','NDB03006'],false,true),
('R529','Tỉ số đảo ngược (lấy số bé chia số lớn hoặc ngược lại)','Tính tỉ số phần trăm hai đại lượng nhưng chia ngược vai trò (so với số sau thay vì số trước). Tính ra kết quả thật.','40 so với 64 → 64 : 40 thay vì 40 : 64','khai_niem',array['NDB03001','NDB02775','NDB03002','NDB03553'],false,true),
('R530','Đảo chiều tăng/giảm','Hiểu ngược hướng thay đổi (tăng thành giảm, nhiều hơn thành ít hơn) nên cộng/trừ ngược khi tính. Tính ra kết quả thật.','Giảm 20% tính thành 100% + 20%','khai_niem',array['NDB02774','NDB02775','NDB02776','NDB03002','NDB03003','NDB03006'],false,true),
('R531','Bỏ sót bước thêm/bớt cuối cùng','Làm đúng phần tính phần trăm nhưng quên cộng/trừ số người, số lượng được thêm/bớt thêm ở cuối đề. Tính ra kết quả thật.','Tổng lúc sau 150 nhưng quên trừ 30 người thêm vào → đáp 150','khai_niem',array['NDB03553','NDB02767','NDB02775'],false,true),
('R532','Hỗn hợp: lấy trung bình cộng nồng độ, không tính theo khối lượng','Trộn hai dung dịch (hợp kim) mà lấy (nồng độ 1 + nồng độ 2) : 2 thay vì tính chất tan tổng : khối lượng tổng. Tính ra kết quả thật.','Trộn 200 g muối 10% với 300 g muối 20% → (10% + 20%) : 2 = 15%','khai_niem',array['NDB02777','NDB02778'],false,true),
('R533','Hỗn hợp/pha loãng: nhầm khối lượng chất tan với khối lượng dung dịch','Lấy p% của dung dịch sau pha (hoặc cộng nước vào chất tan) thay vì giữ nguyên chất tan; hoặc lấy khối lượng dung dịch làm chất tan. Tính ra kết quả thật.','Chất tan 20 g, thêm 30 g nước → coi 50 g là chất tan','khai_niem',array['NDB02777','NDB02778','NDB03004','NDB03005'],false,true),
('R534','Hạt tươi – hạt khô: nhầm phần nước với phần khô','Lấy phần trăm nước thay cho phần trăm khô (hoặc ngược lại) khi quy đổi hạt tươi ↔ hạt khô. Tính ra kết quả thật.','Hạt khô 12% nước → dùng 12% làm phần khô','khai_niem',array['NDB03005','NDB03004'],false,true),
('R535','Lãi suất: quên nhân số kỳ (số tháng, số năm)','Tính lãi một kỳ rồi dùng làm lãi cả thời gian gửi, hoặc nhân sai số kỳ (nhầm tháng với năm). Tính ra kết quả thật.','Gửi 3 năm lãi 6%/năm → chỉ tính lãi 1 năm','khai_niem',array['NDB03007'],false,true),
('R536','Lãi suất: nhầm lãi đơn với lãi gộp (nhập vốn)','Tính lãi nhập vốn như lãi đơn (cùng một số gốc) hoặc ngược lại. Tính ra kết quả thật.','2 kỳ nhập vốn tính thành lãi kỳ 1 × 2','khai_niem',array['NDB03007','NDB03006'],false,true),
('R537','Lãi suất: nhầm tiền lãi với tổng cả gốc lẫn lãi','Trả lời tiền lãi khi đề hỏi cả gốc lẫn lãi (hoặc ngược lại). Tính ra kết quả thật.','Đề hỏi số tiền nhận cả gốc lẫn lãi → ghi riêng tiền lãi','khai_niem',array['NDB03007','NDB02771','NDB02772'],false,true),
('R538','Đổi số thập phân / phân số ↔ phần trăm: dịch dấu phẩy sai hướng hoặc sai số chữ số','Đổi 0,07 thành 70% (dịch một chữ số), 3/8 thành 3,8% hoặc ngược lại. Tính ra kết quả thật.','0,075 → 75% (đúng 7,5%)','tinh',array['NDB03000','NDB02767','NDB02768'],false,true),
('R539','Phần trăm: tính dở bước (tính xong bước một lấy làm đáp số)','Thu số đã tính ở bước giữa (ví dụ giá sau lần giảm thứ nhất, lượng đã dùng) làm đáp số của cả bài.','Giảm giá kép: lấy giá sau lần giảm đầu','khai_niem',array['NDB02774','NDB02769','NDB03006','NDB03002','NDB03003'],false,true),
('R540','Phần trăm: lệch 1 hàng hoặc 1 đơn vị ở bước tính cuối (dự phòng)','Làm đúng cách nhưng đáp số lệch đúng một chữ số/đơn vị ở bước tính cuối (nhớ, dấu phẩy).','72 000 → 7 200 hoặc 73 000','tinh',array['NDB02767','NDB02768','NDB02769','NDB02770','NDB02771','NDB02772','NDB02773','NDB02774','NDB02775','NDB02776','NDB03000','NDB03001','NDB03002','NDB03003','NDB03004','NDB03005','NDB03006','NDB03007','NDB03553','NDB02777','NDB02778'],true,true)
